export function ensureNoDisposablesAreLeakedInTestSuite(): Pick<DisposableStore, 'add'> {
	let tracker: DisposableTracker | undefined;
	let store: DisposableStore;
	setup(() => {
		store = new DisposableStore();
		tracker = new DisposableTracker();
		setDisposableTracker(tracker);
	});

	teardown(function (this: import('mocha').Context) {
		store.dispose();
		setDisposableTracker(null);
		if (this.currentTest?.state !== 'failed') {
			const result = tracker!.computeLeakingDisposables();
			if (result) {
				console.error(result.details);
				throw new Error(`There are ${result.leaks.length} undisposed disposables!${result.details}`);
			}
		}
	});

	// Wrap store as the suite function is called before it's initialized
	const testContext = {
		add<T extends IDisposable>(o: T): T {
			return store.add(o);
		}
	};

const { assertCleanState } = await loadFn('vs/workbench/test/common/utils');

suite('Tests are using suiteSetup and setup correctly', () => {
	test('assertCleanState - check that registries are clean at the start of test running', () => {
		assertCleanState();
	});
});

setup(async () => {
	await perTestCoverage?.startTest();
});

teardown(async () => {
	await perTestCoverage?.finishTest(currentTest.file, currentTest.fullTitle());

	// should not have unexpected output
	if (_testsWithUnexpectedOutput && !opts.dev) {
		assert.ok(false, 'Error: Unexpected console output in test run. Please ensure no console.[log|error|info|warn] usage in tests or runtime errors.');
	}

	// should not have unexpected errors
	const errors = _unexpectedErrors.concat(_loaderErrors);
	if (errors.length) {
		const msg = [];
		for (const error of errors) {
			console.error(`Error: Test run should not have unexpected errors:\n${error}`);
			msg.push(String(error));
		}
		assert.ok(false, `Error: Test run should not have unexpected errors:\n${msg.join('\n')}`);
	}
});

suiteTeardown(() => { // intentionally not in teardown because some tests only cleanup in suiteTeardown

	// should have cleaned up in registries
	assertCleanState();
});

export function installConversationLensResizeObserverHarness(): void {
	// Must run at suite-definition time (loadTests), before mocha.run() binds
	// Runner#uncaught to the current `_uncaught`. Console wrap runs after
	// renderer.js unexpected-output hooks so 0px warns never set that flag.
	patchMochaUncaught();
	installCaptureListener();
	wrapProcessListeners();
	wrapUnexpectedErrorHandler();
	wrapConsoleZeroPxMeasure();
	suiteSetup(() => {
		// mocha.run() assigns window.onerror after modules load.
		wrapWindowOnError();
	});
}

